-- schema.sql - the 8 DFUA tables + 5 indexes (SPEC section 5). Requirement: FR-4.1.
-- Safe to run more than once (CREATE TABLE IF NOT EXISTS).
-- Primary keys are UUIDs (CHAR(36)) generated by the server with crypto.randomUUID().

CREATE TABLE IF NOT EXISTS admins (
  admin_id      CHAR(36)     NOT NULL PRIMARY KEY,
  email         VARCHAR(255) NOT NULL UNIQUE,
  password_hash CHAR(60)     NOT NULL,            -- bcrypt hash only, never the password (NFR-3.3)
  created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS forms (
  form_id      CHAR(36)     NOT NULL PRIMARY KEY,
  admin_id     CHAR(36)     NOT NULL,
  title        VARCHAR(255) NOT NULL,
  status       ENUM('draft','published','unpublished') NOT NULL DEFAULT 'draft',
  share_link   VARCHAR(255) NULL UNIQUE,          -- NULL until published (UNIQUE allows many NULLs)
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  published_at TIMESTAMP    NULL,
  INDEX idx_forms_admin (admin_id, status),
  FOREIGN KEY (admin_id) REFERENCES admins (admin_id)
);

CREATE TABLE IF NOT EXISTS fields (
  field_id    CHAR(36)     NOT NULL PRIMARY KEY,
  form_id     CHAR(36)     NOT NULL,
  field_type  ENUM('text','email','number','dropdown','file') NOT NULL,
  label       VARCHAR(255) NOT NULL,
  is_required BOOLEAN      NOT NULL DEFAULT FALSE,
  position    INT          NOT NULL,              -- order of the field in the form
  validations JSON         NULL,                  -- e.g. {"format":"email","maxFileSizeMB":5,"options":[...]}
  FOREIGN KEY (form_id) REFERENCES forms (form_id)
);

CREATE TABLE IF NOT EXISTS sessions (
  session_id CHAR(36)  NOT NULL PRIMARY KEY,
  form_id    CHAR(36)  NOT NULL,
  started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ended_at   TIMESTAMP NULL,
  status     ENUM('active','submitted','abandoned') NOT NULL DEFAULT 'active',
  ip_hash    CHAR(64)  NOT NULL,                  -- SHA-256 hash, raw IP is never stored (NFR-3.2)
  INDEX idx_sessions_form_status (form_id, status),
  FOREIGN KEY (form_id) REFERENCES forms (form_id)
);

CREATE TABLE IF NOT EXISTS events (
  event_id   CHAR(36)     NOT NULL PRIMARY KEY,
  session_id CHAR(36)     NOT NULL,
  field_id   CHAR(36)     NULL,                   -- NULL for session-level events
  form_id    CHAR(36)     NOT NULL,
  event_type ENUM('focus','input','blur','error','correction','field_completed',
                  'form_opened','form_submitted','form_abandoned') NOT NULL,
  timestamp  TIMESTAMP(3) NOT NULL,               -- millisecond precision: needed for time-per-field
  metadata   JSON         NULL,                   -- never contains typed text (NFR-3.2)
  INDEX idx_events_session_ts (session_id, timestamp),
  INDEX idx_events_form_field (form_id, field_id),
  FOREIGN KEY (session_id) REFERENCES sessions (session_id),
  FOREIGN KEY (field_id)   REFERENCES fields (field_id),
  FOREIGN KEY (form_id)    REFERENCES forms (form_id)
);

CREATE TABLE IF NOT EXISTS submissions (
  submission_id CHAR(36)  NOT NULL PRIMARY KEY,
  session_id    CHAR(36)  NOT NULL UNIQUE,       -- one submission per session
  form_id       CHAR(36)  NOT NULL,
  submitted_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (session_id) REFERENCES sessions (session_id),
  FOREIGN KEY (form_id)    REFERENCES forms (form_id)
);

CREATE TABLE IF NOT EXISTS field_responses (
  response_id   CHAR(36) NOT NULL PRIMARY KEY,
  submission_id CHAR(36) NOT NULL,
  field_id      CHAR(36) NOT NULL,
  value         TEXT     NULL,                    -- what the respondent submitted (only here, not in events)
  FOREIGN KEY (submission_id) REFERENCES submissions (submission_id),
  FOREIGN KEY (field_id)      REFERENCES fields (field_id)
);

CREATE TABLE IF NOT EXISTS recommendations (
  rec_id       CHAR(36)  NOT NULL PRIMARY KEY,
  form_id      CHAR(36)  NOT NULL,
  field_id     CHAR(36)  NOT NULL,
  priority     ENUM('high','medium','low') NOT NULL,
  reason       TEXT      NOT NULL,
  suggestion   TEXT      NOT NULL,
  generated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_recs_form_priority (form_id, priority),
  FOREIGN KEY (form_id)  REFERENCES forms (form_id),
  FOREIGN KEY (field_id) REFERENCES fields (field_id)
);
